import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void relu_kernel(const scalar_t* __restrict__ input,
                            scalar_t* __restrict__ output,
                            size_t N) {
    const size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N) {
        const scalar_t x = input[idx];
        // Convert to float for comparison (works for half and float)
        const float xv = static_cast<float>(x);
        output[idx] = (xv > 0.0f) ? x : scalar_t(0);
    }
}

void relu_fp16(torch::Tensor input, torch::Tensor output) {
    const size_t N = input.numel();
    const int threads = 256;
    const int blocks = static_cast<int>((N + threads - 1) / threads);
    const auto stream = at::cuda::getCurrentCUDAStream();

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "relu_fp16", ([&] {
        relu_kernel<scalar_t><<<blocks, threads, 0, stream>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            N);
    }));

    // Optional error check (can be omitted for performance)
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch failed: ", cudaGetErrorString(err));
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("relu_fp16", &relu_fp16, "ReLU activation for fp16 tensors (CUDA)");
}
'''

# Compile the inline extension
relu_ext = load_inline(
    name="relu_fp16_ext",
