    """
    Drop‑in replacement for the reference Model using a custom CUDA ReLU kernel.
    All tensors are expected to be half‑precision (float16).
    """
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is contiguous float16 on the current CUDA device
        x = x.to(dtype=torch.float16, device='cuda', non_blocking=True).contiguous()
        out = torch.empty_like(x)
        relu_ext.relu_fp16(x, out)
